CREATE TABLE hub_leads(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',company TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'Manual entry',campaign_id TEXT REFERENCES hub_campaign_plans(id),assignee_id TEXT REFERENCES hub_users(id),stage TEXT NOT NULL CHECK(stage IN ('New','Contacted','Qualified','Won','Lost')),follow_up TEXT,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX hub_leads_brand ON hub_leads(workspace_id,brand_id,updated_at);
CREATE TABLE hub_lead_notes(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES hub_leads(id),author_id TEXT NOT NULL REFERENCES hub_users(id),body TEXT NOT NULL,created_at INTEGER NOT NULL);
